import hashlib, json
from pathlib import Path
root = Path('products/services/open-software-tenders')
target = Path('products/services/tender-amendment-evidence/revision-inventory.json')
processes = {'ocds-h6vhtk-07b55c': {}, 'ocds-h6vhtk-07b6cb': {}, 'ocds-h6vhtk-07b83e': {}}
for path in sorted(root.rglob('*.json')):
    try:
        raw = path.read_bytes()
        package = json.loads(raw)
    except (OSError, ValueError):
        continue
    if not isinstance(package, dict):
        continue
    releases = list(package.get('releases') or [])
    for record in package.get('records') or []:
        if isinstance(record, dict):
            releases.extend(record.get('releases') or [])
    for release in releases:
        if not isinstance(release, dict):
            continue
        ocid = release.get('ocid')
        release_id = release.get('id')
        if ocid not in processes or not isinstance(release_id, str):
            continue
        tender = release.get('tender') or {}
        entry = {'path': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'date': release.get('date'), 'tags': release.get('tag'), 'tender_status': tender.get('status'), 'deadline': (tender.get('tenderPeriod') or {}).get('endDate'), 'has_tender_body': bool(tender)}
        processes[ocid].setdefault(release_id, []).append(entry)
result = {'scope': 'Committed JSON under open-software-tenders only. Distinct release IDs can include other stages or references and require source inspection. Saved status does not verify current availability.', 'processes': processes}
target.parent.mkdir(parents=True, exist_ok=True)
target.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(target.read_text(encoding='utf-8'))
